SELECT COUNT(1)
FROM biz_tracking_node_dict
WHERE node_code = #{nodeCode}
  AND api_code = #{apiCode}
  AND node_type = #{nodeType}
    LIMIT 1

mapper.update:
UPDATE biz_tracking_node_dict
SET update_time = NOW(),
    is_active = 1
WHERE node_code = #{nodeCode}
  AND api_code = #{apiCode}
  AND node_type = #{nodeType}
